contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length == v.length, "length mismatch");
        uint256[] memory beforeBal = new uint256[](_tos.length);
        for (uint256 i = 0; i < _tos.length; i++) {
            (bool s, bytes memory d) = caddress.staticcall(abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)")), _tos[i]));
            require(s && d.length >= 32, "balanceOf read failed");
            beforeBal[i] = abi.decode(d, (uint256));
        }
        bool reverted;
        try c.transfer(from, caddress, _tos, v) returns (bool) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!reverted) {
            for (uint256 i = 0; i < _tos.length; i++) {
                (bool s, bytes memory d) = caddress.staticcall(abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)")), _tos[i]));
                require(s && d.length >= 32, "post balanceOf read failed");
                uint256 afterBal = abi.decode(d, (uint256));
                assert(afterBal == beforeBal[i] + v[i]);
            }
        }
        assert(reverted || _tos.length > 0);
    }
    receive() external payable {}
}

